import{_ as n}from"./chunks/Audio.COine8Wh.js";import{_ as i}from"./chunks/Tags.BJ536pW3.js";import{c as r,o,j as a,G as t,ae as s,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const m=JSON.parse('{"title":"Sloan Canyon Conservation and Lateral Pipeline Act","description":"","frontmatter":{"legisId":"2026-05-19-sloan-canyon-conservation-and-lateral-pipeline-act","title":"Sloan Canyon Conservation and Lateral Pipeline Act","displayTitle":"Sloan Canyon Conservation and Lateral Pipeline Act","lawNumber":"119-91","billNumber":"H.R. 972","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ91.xml","publishDate":"2026-05-19T00:00:00-05:00","industries":["environment","government-operations","transportation"],"agencies":["Department of the Interior"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Sloan Canyon Conservation and Lateral Pipeline Act\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2026-05-19-sloan-canyon-conservation-and-lateral-pipeline-act\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Sloan Canyon Conservation and Lateral Pipeline Act\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2026-05-19-sloan-canyon-conservation-and-lateral-pipeline-act\\",\\"datePublished\\":\\"2026-05-19T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2026-05-19-sloan-canyon-conservation-and-lateral-pipeline-act\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2026-05-19-sloan-canyon-conservation-and-lateral-pipeline-act.md","filePath":"congress-bills/2026-05-19-sloan-canyon-conservation-and-lateral-pipeline-act.md","lastUpdated":1788887623000}'),d={name:"congress-bills/2026-05-19-sloan-canyon-conservation-and-lateral-pipeline-act.md"},y=Object.assign(d,{setup(c){return(p,e)=>(o(),r("div",null,[e[0]||(e[0]=a("h1",{id:"sloan-canyon-conservation-and-lateral-pipeline-act",tabindex:"-1"},[l("Sloan Canyon Conservation and Lateral Pipeline Act "),a("a",{class:"header-anchor",href:"#sloan-canyon-conservation-and-lateral-pipeline-act","aria-label":'Permalink to "Sloan Canyon Conservation and Lateral Pipeline Act"'},"​")],-1)),t(n),t(i,{list:"/congress-bills"}),e[1]||(e[1]=s('<p>Signed into law on Tuesday, May 19, 2026. Public Law 119-91, H.R. 972.</p><p><strong>Headline:</strong> The law expands Sloan Canyon’s protected area while authorizing land access for a Southern Nevada water pipeline.</p><p><strong>Why it matters:</strong> It adds 9,290 acres to the national conservation area and advances water infrastructure while protecting wilderness, surface resources, and existing utility corridors.</p><p><strong>What the law does:</strong></p><ul><li>Expands the Sloan Canyon National Conservation Area from 48,438 acres to 57,728 acres using a May 20, 2024, map.</li><li>Requires the Department of the Interior to grant the Southern Nevada Water Authority temporary and permanent rights-of-way within one year at no cost.</li><li>Allows geotechnical work and the construction and operation of the Horizon Lateral Pipeline and related infrastructure.</li><li>Allows the Water Authority to use or dispose of excavated tunneling material and requires suitable federal disposal land to be identified within 30 days after the rights-of-way are granted.</li><li>Bars permanent harm to surface resources and prohibits rights-of-way through or beneath designated wilderness.</li><li>Preserves existing transmission and utility corridors and permits authorized work and certain new rights-of-way within them, subject to environmental laws and federal conditions.</li></ul><p><strong>Who it affects:</strong></p><ul><li>The Southern Nevada Water Authority and communities served by its water infrastructure.</li><li>Utility operators using existing transmission and utility corridors.</li><li>Visitors, wildlife, and conservation resources within Sloan Canyon.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Southern Nevada residents may see water infrastructure move forward without federal right-of-way fees.</li><li>Visitors gain 9,290 additional acres within the conservation area, with wilderness and surface protections maintained.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="sloan-canyon-conservation-and-lateral-pipeline-act-1" tabindex="-1">Sloan Canyon Conservation and Lateral Pipeline Act <a class="header-anchor" href="#sloan-canyon-conservation-and-lateral-pipeline-act-1" aria-label="Permalink to &quot;Sloan Canyon Conservation and Lateral Pipeline Act&quot;">​</a></h3><p>This law expands the Sloan Canyon National Conservation Area from 48,438 acres to 57,728 acres using a new 2024 boundary map. It also requires the federal government to provide the Southern Nevada Water Authority with free rights-of-way for the Horizon Lateral Pipeline and related infrastructure, while protecting conservation resources, wilderness, and existing utility rights.</p><p><strong>Key takeaways:</strong></p><ul><li>The conservation area&#39;s boundary is expanded by 9,290 acres under a map dated May 20, 2024.</li><li>The Interior Department must grant specified temporary and permanent rights-of-way to the Southern Nevada Water Authority within one year, without charging rent or other fees.</li><li>The rights-of-way may be used for geotechnical investigations and for constructing and operating water transmission facilities and related infrastructure.</li><li>The Water Authority may use or dispose of materials excavated during pipeline tunneling, and the parties must identify suitable federal disposal land within 30 days after the rights-of-way are granted.</li><li>Pipeline construction may not permanently harm surface resources in the conservation area, and no right-of-way may pass through or under designated wilderness.</li><li>The boundary expansion preserves existing transmission and utility corridors and allows authorized utility work and certain new utility rights-of-way within existing corridors, subject to applicable environmental laws and federal conditions.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ91.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ91.xml</a></p>',15))]))}});export{m as __pageData,y as default};
